mapper.select:
select t.job_id, t.model, t.product, t.agent, t.job_name, t.cron_expression, t.plugin, t.program_name, t.auto_start, t.create_time, t.creator from ww_cron t where 1=1
and t.product = #{product}
and (t.product = #{nullOrProduct} or t.product is null)
and t.agent = #{agent}
and (t.agent = #{nullOrAgent} or t.agent is null)
and instr(t.agent, #{lAgent}) > 0
and t.job_id = #{jobId}
and instr(t.job_id, #{lJobId}) > 0
and exists ( select tsupr.product_id From ww_sys_user tsu,ww_product tp,ww_sys_user_product_ref tsupr where tsu.login_name=tsupr.user_id and tp.p_id=tsupr.product_id and (tp.p_id=t.product or t.product is null) and tsu.login_name=#{loginName} )
and t.job_id in
#{item}

mapper.update:
    UPDATE ww_cron set auto_start = 0
	 WHERE job_id in

		#{item}
